parameters.functionScript:
// The whole store. A habit's ticks are always read and written with the habit
// itself (docs/ARCHITECTURE.md), so one node reads localStorage, applies the
// command it was handed, writes the list back whole, and returns what the page
// should draw. A press reaches it as a string because a signal carries no value.
//
//   add:<name>        a new habit
//   set:<id>:<0|1>    today's tick for one habit — the value it should hold
//   remove:<id>       the habit goes, and its history with it
//
// Anything else, including nothing at all, is a plain re-read: that is what
// draws the list when the app opens, because no Run signal is wired.
const KEY = "habit-tracker.habits.v1";
const WEEKDAY = ["S", "M", "T", "W", "T", "F", "S"];

const pad = (number) => (number < 10 ? "0" + number : "" + number);

const dayKey = (date) =>
  date.getFullYear() + "-" + pad(date.getMonth() + 1) + "-" + pad(date.getDate());

const today = dayKey(new Date());

const newId = () =>
  "h" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);

const readAll = () => {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY));
    return Array.isArray(saved) ? saved : [];
  } catch (error) {
    return [];
  }
};

const saveAll = (habits) => {
  try {
    localStorage.setItem(KEY, JSON.stringify(habits));
  } catch (error) {
    // A browser that refuses storage still works for this visit.
  }
};

// The last seven days, oldest first, in the shape the page draws.
const lastSevenDays = () => {
  const days = [];
  const cursor = new Date();
  cursor.setDate(cursor.getDate() - 6);
  for (let step = 0; step < 7; step++) {
    const key = dayKey(cursor);
    days.push({ id: key, letter: WEEKDAY[cursor.getDay()], isToday: key === today });
    cursor.setDate(cursor.getDate() + 1);
  }
  return days;
};

// Counts back from today, or from yesterday while today is unticked: a streak is
// lost when a whole day is missed, not at midnight.
const streakOf = (ticks, todayKey) => {
  const done = (key) => ticks.indexOf(key) !== -1;
  const cursor = new Date();
  if (!done(todayKey)) cursor.setDate(cursor.getDate() - 1);
  let streak = 0;
  while (done(dayKey(cursor))) {
    streak++;
    cursor.setDate(cursor.getDate() - 1);
  }
  return streak;
};

const streakLabel = (streak) => {
  if (streak === 0) return "No streak yet";
  if (streak === 1) return "1 day in a row";
  return streak + " days in a row";
};

let habits = readAll();
const command = Inputs.command || "";
let added = false;

if (command.indexOf("add:") === 0) {
  const name = command.slice(4).trim();
  const taken = habits.some(
    (habit) => (habit.name || "").trim().toLowerCase() === name.toLowerCase()
  );
  if (name && !taken) {
    habits.push({
      id: newId(),
      name: name,
      createdAt: new Date().toISOString(),
      ticks: [],
    });
    saveAll(habits);
    added = true;
  }
} else if (command.indexOf("set:") === 0) {
  const rest = command.slice(4);
  const cut = rest.lastIndexOf(":");
  const habit = habits.find((one) => one.id === rest.slice(0, cut));
  if (habit) {
    const ticks = Array.isArray(habit.ticks) ? habit.ticks : [];
    const at = ticks.indexOf(today);
    if (rest.slice(cut + 1) === "1" && at === -1) ticks.push(today);
    if (rest.slice(cut + 1) === "0" && at !== -1) ticks.splice(at, 1);
    habit.ticks = ticks;
    saveAll(habits);
  }
} else if (command.indexOf("remove:") === 0) {
  const kept = habits.filter((habit) => habit.id !== command.slice(7));
  if (kept.length !== habits.length) {
    habits = kept;
    saveAll(habits);
  }
}

const week = lastSevenDays();
const list = habits.map((habit) => {
  const ticks = Array.isArray(habit.ticks) ? habit.ticks : [];
  const done = (key) => ticks.indexOf(key) !== -1;
  return {
    id: habit.id,
    name: habit.name,
    streakLabel: streakLabel(streakOf(ticks, today)),
    doneToday: done(today),
    days: week.map((day) => ({
      id: day.id,
      letter: day.letter,
      done: done(day.id),
      isToday: day.isToday,
    })),
  };
});

Outputs.habits = list;
Outputs.count = list.length;
Outputs.namesLower = list.map((habit) => habit.name.trim().toLowerCase());
Outputs.summary =
  list.length === 0
    ? ""
    : list.filter((habit) => habit.doneToday).length + " of " + list.length + " done today";
Outputs.todayLabel = new Date().toLocaleDateString(undefined, {
  weekday: "long",
  day: "numeric",
  month: "long",
});
if (added) Outputs.added();
